+const { useState, useRef, useEffect } = React;
+
+const Modal = ({ isOpen, onClose, title, children }) => {
+  const dialogRef = useRef(null);
+
+  useEffect(() => {
+    const dialog = dialogRef.current;
+    if (isOpen) {
+      if (!dialog.open) {
+        dialog.showModal();
+      }
+    } else {
+      if (dialog.open) {
+        dialog.close();
+      }
+    }
+  }, [isOpen]);
+
+  useEffect(() => {
+    const dialog = dialogRef.current;
+    const handleCancel = (e) => {
+      e.preventDefault();
+      onClose();
+    };
+    dialog.addEventListener('cancel', handleCancel);
+    return () => dialog.removeEventListener('cancel', handleCancel);
+  }, [onClose]);
+
+  return (
+    <dialog ref={dialogRef} aria-labelledby="modal-title">
+      <div className="modal-content">
+        <div className="modal-header">
+          <h2 id="modal-title" className="modal-title">{title}</h2>
+        </div>
+        <div className="modal-body">
+          {children}
+        </div>
+      </div>
+    </dialog>
+  );
+};
+
+const App = () => {
+  const [isModalOpen, setIsModalOpen] = useState(false);
+  const triggerRef = useRef(null);
+
+  const openModal = () => setIsModalOpen(true);
+  const closeModal = () => {
+    setIsModalOpen(false);
+    // Focus is restored automatically by <dialog> on close
+  };
+
+  const handleDelete = () => {
+    console.log("Image deleted");
+    closeModal();
+  };
+
+  return (
+    <main className="container">
+      <h1>Image Preview</h1>
+      <img 
+        src="https://images.unsplash.com/photo-1506744038136-46273834b3fb?auto=format&fit=crop&w=800&q=80" 
+        alt="Mountain landscape with a lake reflecting the sky" 
+        className="image-preview"
+      />
+      <div className="actions">
+        <button 
+          ref={triggerRef}
+          className="btn btn-danger trigger" 
+          onClick={openModal}
+        >
+          Delete Image
+        </button>
+      </div>
+
+      <Modal 
+        isOpen={isModalOpen} 
+        onClose={closeModal} 
+        title="Delete this image?"
+      >
+        <p>This will permanently remove the image from your library. This action cannot be undone.</p>
+        <div className="modal-footer">
+          <button className="btn btn-secondary" onClick={closeModal}>
+            Cancel
+          </button>
+          <button className="btn btn-danger btn-primary" onClick={handleDelete} style={{backgroundColor: 'var(--danger)'}}>
+            Delete
+          </button>
+        </div>
+      </Modal>
+    </main>
+  );
+};
+
+const root = ReactDOM.createRoot(document.getElementById('root'));
+root.render(<App />);
+
')

